typedef int nvlMutex;

struct nvlStream
{
  int idx;
  unsigned int startSector;
  unsigned int endSector;
  unsigned int readSector;
  unsigned int filesize;
  int bytes_in_last_sect;
  int bufsize;
  char *buf;
  char *endbuf;
  char *pRead;
  char *pWrite;
  char *pLock;
  char *pEndOfData;
  char *pStartOfData;
  int private_buffer;
  int bitrate;
  int flags;
  int available;
  nvlMutex mtx;
  int lp_skip;
  int requireRewind;
  int fh;
};

enum nvlMutexMode { NVL_MUTEX_BLOCK, NVL_MUTEX_NOBLOCK };

extern int nvlLockMutex(nvlMutex *, nvlMutexMode);
extern void nvlUnlockMutex(nvlMutex *);
extern "C" int sceRead(int, void *, int);
extern "C" int sceLseek(int, int, int);
