#define assert_at(condition, line, expression) \
  ((condition) ? (void)0 : __assert(source_file, line, expression))

static void nvlReadHost(nvlStream *s)
{
  int byte_num = 0, res;

  if (s->pLock && s->pLock >= s->pWrite)
  {
    byte_num = s->pLock - s->pWrite;
  }
  else if (s->pRead == 0 || s->pRead < s->pWrite ||
           (s->pRead == s->pWrite && s->available == 0))
  {
    byte_num = s->endbuf - s->pWrite;
    assert_at(byte_num == 0 || byte_num >= 2048, 541, assert_sector_size);
  }
  else
  {
    assert_at(s->pRead >= s->pWrite, 545, assert_read_order);
    byte_num = s->pRead - s->pWrite;
  }
  if (byte_num < 2048)
  {
    byte_num = 0;
  }
  else if (byte_num > 0x100000)
  {
    byte_num = 0x100000;
  }
  byte_num &= ~(2048 - 1);

  if (byte_num)
  {
    nvlLockMutex(&s->mtx, NVL_MUTEX_BLOCK);
    if (s->flags & 3)
    {
      nvlUnlockMutex(&s->mtx);
      return;
    }
    s->flags |= 2;
    nvlUnlockMutex(&s->mtx);

    res = sceRead(s->fh, s->pWrite, byte_num);
    FlushCache(0);
    assert_at(res >= 0, 571, assert_read_result);

    nvlLockMutex(&s->mtx, NVL_MUTEX_BLOCK);
    s->pWrite += byte_num;
    assert_at(s->pWrite <= s->endbuf, 575, assert_write_bounds);
    if (res < byte_num)
    {
      assert_at(s->pEndOfData == 0, 578, assert_end_data);
      s->flags |= 8;
      s->pEndOfData = s->pWrite - byte_num + res;
      if (s->flags & 4)
      {
        if (s->pWrite >= s->endbuf)
        {
          s->pWrite = s->buf;
        }
        s->pStartOfData = s->pWrite;
        sceLseek(s->fh, s->lp_skip, 0);
      }
    }
    else if (s->flags & 8)
    {
      s->flags &= ~8;
    }
    s->available += res;
    if (s->pWrite == s->endbuf)
    {
      s->pWrite = s->buf;
    }
    if (s->pRead == 0)
    {
      s->pRead = s->buf;
    }
    s->flags &= ~2;
    nvlUnlockMutex(&s->mtx);
  }
}
